import json
import os
import unittest
from pathlib import Path


class TestExperimentEvidenceSchema(unittest.TestCase):
    def setUp(self) -> None:
        # Ensure evidence is generated by running run.py in-process
        evidence_dir = Path(os.environ.get("BOOKMAS_EVIDENCE_DIR", "/evidence"))
        evidence_path = evidence_dir / "results.json"
        if not evidence_path.exists():
            import run as experiment_run

            experiment_run.main()
        self.evidence_dir = evidence_dir
        self.evidence_path = evidence_path

    def test_evidence_file_exists(self) -> None:
        self.assertTrue(self.evidence_path.exists(), "results.json must exist")

    def test_evidence_schema(self) -> None:
        with self.evidence_path.open("r", encoding="utf-8") as f:
            data = json.load(f)

        # Top-level required fields
        self.assertIn("chapter", data)
        self.assertIn("experiment_id", data)
        self.assertIn("environment", data)
        self.assertIn("runs", data)

        self.assertIsInstance(data["chapter"], int)
        self.assertEqual(data["experiment_id"], "exp-ch5-llm-instrumentation-otel-rca-signals-v1")

        env = data["environment"]
        self.assertIsInstance(env, dict)
        self.assertIn("os", env)
        self.assertIn("python", env)
        self.assertIsInstance(env["os"], str)
        self.assertIsInstance(env["python"], str)

        runs = data["runs"]
        self.assertIsInstance(runs, list)
        self.assertGreaterEqual(len(runs), 2)

        variants = {"baseline": 0, "treatment": 0}

        for run in runs:
            self.assertIn("variant", run)
            self.assertIn("workload_id", run)
            self.assertIn("run_id", run)
            self.assertIn("success", run)
            self.assertIn("metrics", run)

            self.assertIsInstance(run["variant"], str)
            self.assertIsInstance(run["workload_id"], str)
            self.assertIsInstance(run["run_id"], str)
            self.assertIsInstance(run["success"], bool)
            self.assertIsInstance(run["metrics"], dict)

            v = run["variant"]
            if v in variants:
                variants[v] += 1

            # All metrics values must be numbers
            for k, v in run["metrics"].items():
                self.assertIsInstance(v, (int, float), f"metric {k} must be numeric")

        # At least one baseline and one treatment run
        self.assertGreaterEqual(variants["baseline"], 1)
        self.assertGreaterEqual(variants["treatment"], 1)


if __name__ == "__main__":
    unittest.main()
